const bank = "BRADESCO";
const linhas = $input.item.json.lines;

// ============================================================
// CLIENTE
// ============================================================

const clientMatch = linhas[2].match(/Nome:\s*([^\r\n]+)/i);

const clientName = clientMatch
  ? clientMatch[1].trim()
  : null;

// ============================================================
// FUNÇÕES AUXILIARES
// ============================================================

// Converte "3.806,44" para 3806.44
function parseValor(valor) {
  return Number(
    valor
      .replace(/\./g, "")
      .replace(",", ".")
  );
}

// Formata o valor novamente para pt-BR
function formatarValor(valor) {
  return valor.toLocaleString("pt-BR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

// ============================================================
// IDENTIFICA TIPO PELA DESCRIÇÃO
// ============================================================

function identificarTipoPorDescricao(descricao) {

  const texto = descricao.toUpperCase();

  // Operações que normalmente representam ENTRADA
  const entradas = [
    "RENDIMENTOS",
    "TRANSFERENCIA PIX REM:",
    "PIX RECEBIDO",
    "DEPOSITO",
    "RECEBIMENTO",
    "CREDITO"
  ];

  // Operações que normalmente representam SAÍDA
  const saidas = [
    "TRANSFERENCIA PIX DES:",
    "PAGTO ELETRON COBRANCA",
    "PACOTE DE SERVICOS",
    "TAR 2 VIA CARTAO",
    "ENCARGOS LIMITE DE CRED",
    "IOF S/ UTILIZACAO LIMITE",
    "GASTOS CARTAO DE CREDITO",
    "PIX QR CODE",
    "DEBITO"
  ];

  // Primeiro verifica entradas
  if (entradas.some(item => texto.includes(item))) {
    return "ENTRADA";
  }

  // Depois verifica saídas
  if (saidas.some(item => texto.includes(item))) {
    return "SAIDA";
  }

  // Não conseguiu identificar
  return null;
}

// ============================================================
// REGEX
// ============================================================

// Data no começo da linha
const dataRegex = /^(\d{2}\/\d{2}\/\d{4})\s*(.*)$/;

// Final de uma transação:
// DOCUMENTO VALOR SALDO
//
// Exemplos:
// 0506731 1,34 335,73
// 0000096 3.701,03 203,47
// 5373634 0,06 10.394,99
const finalTransacaoRegex =
  /(\d{7})\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/;

// ============================================================
// PROCESSAMENTO
// ============================================================

const transacoes = [];

let dataAtual = null;
let linhasTransacao = [];

// Saldo anterior utilizado para descobrir entrada/saída
let saldoAnterior = null;


// ============================================================
// FINALIZA TRANSAÇÃO
// ============================================================

function processarTransacao() {

  if (!linhasTransacao.length) {
    return;
  }

  const texto = linhasTransacao.join(" ").trim();

  const match = texto.match(finalTransacaoRegex);

  if (!match) {
    linhasTransacao = [];
    return;
  }

  const documento = match[1];
  const valorBruto = match[2];
  const saldoAtualBruto = match[3];

  const valor = parseValor(valorBruto);
  const saldoAtual = parseValor(saldoAtualBruto);

  // Remove documento + valor + saldo da descrição
  const descricao = texto
    .replace(finalTransacaoRegex, "")
    .trim()
    .replace(/\s+/g, " ");

  // ==========================================================
  // IGNORA LANÇAMENTOS SEM MOVIMENTAÇÃO
  // ==========================================================

  if (valor === 0) {
    saldoAnterior = saldoAtual;
    linhasTransacao = [];
    return;
  }

  // ==========================================================
  // IDENTIFICA TIPO DA TRANSAÇÃO
  // ==========================================================

  let tipoTransacao = null;

  // ----------------------------------------------------------
  // 1. PRIMEIRA TENTATIVA:
  //    COMPARAÇÃO DO SALDO
  // ----------------------------------------------------------

  if (saldoAnterior !== null) {

    if (saldoAtual > saldoAnterior) {
      tipoTransacao = "ENTRADA";
    }
    else if (saldoAtual < saldoAnterior) {
      tipoTransacao = "SAIDA";
    }
  }

  // ----------------------------------------------------------
  // 2. FALLBACK:
  //    ANÁLISE DA DESCRIÇÃO
  // ----------------------------------------------------------

  if (tipoTransacao === null) {
    tipoTransacao = identificarTipoPorDescricao(descricao);
  }

  // ==========================================================
  // ADICIONA TRANSAÇÃO
  // ==========================================================

  transacoes.push({
    data: dataAtual,
    descricao,
    documento,
    valor: formatarValor(valor),
    tipoTransacao
  });

  // Atualiza o saldo anterior
  saldoAnterior = saldoAtual;

  linhasTransacao = [];
}


// ============================================================
// PERCORRE TODAS AS LINHAS
// ============================================================

for (const linha of linhas) {

  // ==========================================================
  // IGNORA CABEÇALHOS E INFORMAÇÕES QUE NÃO SÃO TRANSAÇÕES
  // ==========================================================

  if (
    linha.startsWith("Bradesco Celular") ||
    linha.startsWith("Data:") ||
    linha.startsWith("Nome:") ||
    linha.startsWith("Extrato de:") ||
    linha.startsWith("Folha:") ||
    linha.startsWith("Data Histórico") ||
    linha.startsWith("Total ") ||
    linha === "Extrato inexistente"
  ) {
    continue;
  }

  // Ignora linhas de separação
  if (!linha) {
    continue;
  }

  // ==========================================================
  // VERIFICA SE COMEÇA UMA NOVA DATA
  // ==========================================================

  const dataMatch = linha.match(dataRegex);

  if (dataMatch) {

    // Se já havia uma transação sendo construída,
    // finaliza antes de começar a próxima
    if (linhasTransacao.length) {
      processarTransacao();
    }

    dataAtual = dataMatch[1];

    const restante = dataMatch[2].trim();

    if (restante) {
      linhasTransacao.push(restante);
    }

    continue;
  }

  // ==========================================================
  // LINHA NORMAL DA TRANSAÇÃO
  // ==========================================================

  linhasTransacao.push(linha);

  // Se a linha contém DOCUMENTO + VALOR + SALDO,
  // chegamos ao final da transação.
  if (finalTransacaoRegex.test(linha)) {
    processarTransacao();
  }
}

// ============================================================
// FINALIZA ÚLTIMA TRANSAÇÃO
// ============================================================

if (linhasTransacao.length) {
  processarTransacao();
}


// ============================================================
// RESULTADO
// ============================================================

const count = transacoes.length;

return {
  bank,
  clientName,
  count,
  transacoes
};

const bank = "BRADESCO";
const lines = $input.item.json.lines;

// ============================================================
// CLIENTE
// ============================================================

let clientMatch;
let clientName;

lines.forEach(l => {
  clientMatch = l.match(/Nome:\s*([^\r\n]+)/i);
  if (clientMatch) clientName = clientMatch[1].trim();
});


// ============================================================
// FUNÇÕES AUXILIARES
// ============================================================

function parseValor(valor) {
  return Number(
    valor
      .replace(/\./g, "")
      .replace(",", ".")
  );
}

function formatarValor(valor) {
  return valor.toLocaleString("pt-BR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function converterData(dataTexto) {

  const match = dataTexto.match(
    /^(\d{2})\/(\d{2})\/(\d{2})$/
  );

  if (!match) {
    return null;
  }

  const [, dia, mes, ano] = match;

  return `${dia}/${mes}/20${ano}`;
}

function dataParaTimestamp(dataTexto) {

  const [dia, mes, ano] = dataTexto.split("/");

  return new Date(
    Number(ano),
    Number(mes) - 1,
    Number(dia)
  ).getTime();
}

// ============================================================
// IDENTIFICA TIPO PELA DESCRIÇÃO
// ============================================================

function identificarTipoPorDescricao(descricao) {

  if (!descricao) {
    return null;
  }

  const texto = descricao
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  const entradas = [
    "TRANSFE PIX",
    "PIX RECEBIDO",
    "RENDIMENTOS",
    "DEPOSITO",
    "RECEBIMENTO",
    "CREDITO"
  ];

  const saidas = [
    "TRANSF PGT MTG",
    "PAGTO",
    "DEBITO",
    "TARIFA",
    "ENCARGO"
  ];

  if (entradas.some(item => texto.includes(item))) {
    return "ENTRADA";
  }

  if (saidas.some(item => texto.includes(item))) {
    return "SAIDA";
  }

  return null;
}

// ============================================================
// REGEX
// ============================================================

// Data isolada:
//
// 07/09/25
// 08/11/25
// 07/10/25
const dataIsoladaRegex =
  /^(\d{2})\/(\d{2})\/(\d{2})$/;


// Data + documento + valor
//
// 07/12/25 0303637 5.667,23
// 08/11/25 6228878 - 5.667,23
const transacaoCompletaRegex =
  /^(\d{2}\/\d{2}\/\d{2})\s+(\d{7})\s+(-\s*)?([\d.]+,\d{2})$/;


// Documento + valor
//
// 0283637 5.667,23
// 5578889 - 5.667,23
const transacaoSemDataRegex =
  /^(\d{7})\s+(-\s*)?([\d.]+,\d{2})$/;


// ============================================================
// CLASSIFICA AS LINHAS
// ============================================================

const linhas = [];

for (let i = 0; i < lines.length; i++) {

  const texto = lines[i];

  // ----------------------------------------------------------
  // TRANSAÇÃO COMPLETA
  // ----------------------------------------------------------

  let match = texto.match(transacaoCompletaRegex);

  if (match) {

    const dataTransacao = converterData(match[1]);

    const documento = match[2];

    const negativo = !!match[3];

    const valorBruto = match[4];

    linhas.push({
      indice: i,
      tipo: "TRANSACAO",
      data: dataTransacao,
      documento,
      valorBruto,
      negativo,
      descricao: null,
      dataExplicita: true
    });

    continue;
  }

  // ----------------------------------------------------------
  // DATA ISOLADA
  // ----------------------------------------------------------

  match = texto.match(dataIsoladaRegex);

  if (match) {

    linhas.push({
      indice: i,
      tipo: "DATA",
      data: converterData(texto)
    });

    continue;
  }

  // ----------------------------------------------------------
  // TRANSAÇÃO SEM DATA
  // ----------------------------------------------------------

  match = texto.match(transacaoSemDataRegex);

  if (match) {

    linhas.push({
      indice: i,
      tipo: "TRANSACAO_SEM_DATA",
      documento: match[1],
      valorBruto: match[3],
      negativo: !!match[2],
      descricao: null,
      dataExplicita: false
    });

    continue;
  }

  // ----------------------------------------------------------
  // DESCRIÇÕES
  // ----------------------------------------------------------

  if (
    /^Transfe Pix$/i.test(texto) ||
    /^Transf Pgt Mtg$/i.test(texto)
  ) {

    linhas.push({
      indice: i,
      tipo: "DESCRICAO",
      descricao: texto
    });

    continue;
  }
}

// ============================================================
// SEPARA OS ELEMENTOS
// ============================================================

const datas = linhas.filter(
  item => item.tipo === "DATA"
);

const transacoesComData = linhas.filter(
  item => item.tipo === "TRANSACAO"
);

const transacoesSemData = linhas.filter(
  item => item.tipo === "TRANSACAO_SEM_DATA"
);

const descricoes = linhas.filter(
  item => item.tipo === "DESCRICAO"
);

// ============================================================
// PROCESSA TRANSAÇÕES QUE JÁ POSSUEM DATA
// ============================================================

const transacoes = [];

for (const item of transacoesComData) {

  const valor = parseValor(item.valorBruto);

  let tipoTransacao;

  if (item.negativo) {
    tipoTransacao = "SAIDA";
  }
  else {
    tipoTransacao = "ENTRADA";
  }

  transacoes.push({
    data: item.data,
    descricao: null,
    documento: item.documento,
    valor: formatarValor(valor),
    tipoTransacao,
    _indice: item.indice
  });
}

// ============================================================
// ASSOCIA TRANSAÇÕES SEM DATA
// ============================================================
//
// O OCR colocou algumas transações em uma região diferente
// da data.
//
// Exemplo:
//
// 07/09/25
// 0283637 5.667,23
// 5578889 - 5.667,23
//
// Porém também pode acontecer:
//
// 9385364 - 5.667,23
// 08/11/25
//
// Por isso usamos a data mais próxima considerando os dois
// lados da linha.
//
// ============================================================

for (const item of transacoesSemData) {

  // ----------------------------------------------------------
  // Procura a data imediatamente anterior
  // ----------------------------------------------------------

  let dataAnterior = null;

  for (let i = datas.length - 1; i >= 0; i--) {

    if (datas[i].indice < item.indice) {
      dataAnterior = datas[i];
      break;
    }
  }

  // ----------------------------------------------------------
  // Procura a próxima data
  // ----------------------------------------------------------

  let dataPosterior = null;

  for (let i = 0; i < datas.length; i++) {

    if (datas[i].indice > item.indice) {
      dataPosterior = datas[i];
      break;
    }
  }

  // ----------------------------------------------------------
  // Calcula distância
  // ----------------------------------------------------------

  let dataEscolhida = null;

  if (dataAnterior && dataPosterior) {

    const distanciaAnterior =
      item.indice - dataAnterior.indice;

    const distanciaPosterior =
      dataPosterior.indice - item.indice;

    // Escolhe a data mais próxima
    if (distanciaAnterior <= distanciaPosterior) {
      dataEscolhida = dataAnterior.data;
    }
    else {
      dataEscolhida = dataPosterior.data;
    }

  }
  else if (dataAnterior) {

    dataEscolhida = dataAnterior.data;

  }
  else if (dataPosterior) {

    dataEscolhida = dataPosterior.data;
  }

  // ----------------------------------------------------------
  // Se não conseguiu encontrar data, ignora
  // ----------------------------------------------------------

  if (!dataEscolhida) {
    continue;
  }

  const valor = parseValor(item.valorBruto);

  const tipoTransacao = item.negativo
    ? "SAIDA"
    : "ENTRADA";

  transacoes.push({
    data: dataEscolhida,
    descricao: null,
    documento: item.documento,
    valor: formatarValor(valor),
    tipoTransacao,
    _indice: item.indice
  });
}

// ============================================================
// ASSOCIA DESCRIÇÕES
// ============================================================
//
// Aqui fazemos uma associação conservadora.
// A descrição é relacionada à transação mais próxima.
//
// ============================================================

for (const descricaoItem of descricoes) {

  let melhorTransacao = null;
  let menorDistancia = Infinity;

  for (const transacao of transacoes) {

    if (transacao.descricao !== null) {
      continue;
    }

    const distancia = Math.abs(
      transacao._indice - descricaoItem.indice
    );

    if (distancia < menorDistancia) {
      menorDistancia = distancia;
      melhorTransacao = transacao;
    }
  }

  if (melhorTransacao) {
    melhorTransacao.descricao =
      descricaoItem.descricao;
  }
}

// ============================================================
// FALLBACK DA DESCRIÇÃO
// ============================================================
//
// Se alguma transação ficou sem descrição, tenta identificar
// pelo próprio tipo.
//
// ============================================================

for (const transacao of transacoes) {

  if (!transacao.descricao) {

    if (transacao.tipoTransacao === "ENTRADA") {
      transacao.descricao = "Transfe Pix";
    }

    if (transacao.tipoTransacao === "SAIDA") {
      transacao.descricao = "Transf Pgt Mtg";
    }
  }
}

// ============================================================
// ORDENA POR DATA
// ============================================================
//
// Mais antiga -> mais recente
//
// ============================================================

transacoes.sort((a, b) => {

  const dataA = dataParaTimestamp(a.data);
  const dataB = dataParaTimestamp(b.data);

  if (dataA !== dataB) {
    return dataA - dataB;
  }

  // Se forem do mesmo dia, mantém a ordem original
  return a._indice - b._indice;
});

// ============================================================
// REMOVE CAMPOS INTERNOS
// ============================================================

for (const transacao of transacoes) {
  delete transacao._indice;
}

// ============================================================
// RESULTADO
// ============================================================

const count = transacoes.length;

return {
  bank,
  clientName,
  count,
  transacoes
};
